// Session05BExplicitEntry.cs
// Lab 1 of 3 - Write an Explicit Backing-Field Property
class Session05BExplicitEntry
{
    private DateTime _clockIn;

    public DateTime ClockIn
    {
        get
        {
            return _clockIn;
        }
        set
        {
            _clockIn = value;
        }
    }
}

// Session05BAutoEntry.cs
// Lab 2 of 3 - Write the Equivalent Auto-Property
class Session05BAutoEntry
{
    public DateTime ClockIn { get; set; }
}

// Session05BPropertyDemo.cs
// Lab 3 of 3 - Compare Both Properties from Main
class Session05BPropertyDemo
{
    public void Run()
    {
        Console.WriteLine("Side Lab 05B");
        DateTime exampleTime = new DateTime(2026, 8, 5, 9, 0, 0);

        var explicitEntry = new Session05BExplicitEntry();
        explicitEntry.ClockIn = exampleTime;
        Console.WriteLine($"Explicit property: {explicitEntry.ClockIn}");

        var autoEntry = new Session05BAutoEntry();
        autoEntry.ClockIn = exampleTime;
        Console.WriteLine($"Auto-property: {autoEntry.ClockIn}");
    }
}

// Add to Program.cs without removing earlier calls
var session05B = new Session05BPropertyDemo();
session05B.Run();
